import fs from 'node:fs';
import assert from 'node:assert/strict';
const root=process.argv[2];
const {importFiles}=await import(root+"/src/project/formats.js");
const {compileProject}=await import(root+"/src/language/compiler.js");
const {VirtualMachine}=await import(root+"/src/runtime/vm.js");
const names=["hello.vbp","hello.bas"];
const project=(await importFiles(new Map(names.map(name=>[name,new Uint8Array(fs.readFileSync(name))])))).project;
assert.equal(project.name,"CorpusHello");
assert.equal(project.startup,"Sub Main");
assert.equal(project.modules.length,1);
const compiled=compileProject(project);
assert.deepEqual(compiled.diagnostics,[]);
const captured=[];
const vm=new VirtualMachine(compiled,{msgBox(text){captured.push(text);return Promise.resolve(1);}});
await vm.start();
assert.deepEqual(captured,["Hello, World!"]);
console.log(captured[0]);
